insert:
onPropertiesChanged: {
if( properties["objectName"] !== undefined ) {
if( properties["objectName"] === "headerArea" ) {
useVolumeArea = properties["useVolumeArea"]
if( voluemeArea.item ) {
volumeAreaBinder.readValues()
}
if( statusVolumeBar.item) {
statusVolumeBarBinder.readValues()
}
}
}
}
Loader {
id:voluemeArea
anchors.top:parent.top
source: useVolumeArea ? "VolumeArea.qml" : ""
onLoaded: {
if(item) {
volumeAreaBinder.readValues()
height = item.height
width = item.width
}
}
Binding {
id:volumeAreaBinder
target:voluemeArea.item
function readValues() {
for(var prop in properties) {
if( prop !== "objectName") {
property = ""
value = properties[prop]
property = prop
}
}
}
}
Connections {
target:voluemeArea.item
ignoreUnknownSignals:true
onVolumeBarClicked: {
header.volumeBarClicked()
}
}
}
Binding {
target: voluemeArea.item
when: voluemeArea.status === Loader.Ready
property: "stateIconList"
value: header.properties ? header.properties["stateIconList"] : null
}
StatusBar{
id:status
compactActive: voluemeArea.item ? voluemeArea.item.compactReady : false
anchors.top:voluemeArea.bottom
stateIconList: header.properties["stateIconList"]
isEnableStatusBarMouseArea: header.properties["isEnableStatusBarMouseArea"]
Connections {
target:status
ignoreUnknownSignals:true
onStatusBarClicked: {
header.statusBarClicked()
}
}
}
Loader {
id:statusVolumeBar
anchors.top:parent.top
source: !useVolumeArea ? "StatusVolumeBar.qml" : ""
onLoaded: {
if(item) {
volumeAreaBinder.readValues()
height = item.height
width = item.width
}
}
Binding {
id:statusVolumeBarBinder
target:statusVolumeBar.item
function readValues() {
for(var prop in properties) {
if( prop !== "objectName") {
property = ""
value = properties[prop]
property = prop
}
}
}
}
Connections{
target: statusVolumeBar.item
onStatusBarClicked: {
header.statusBarClicked()
}
}
}
}
